// Utilities sometimes assemble an interface message before it reaches React.
// Match only catalogued sentences with a substantial literal prefix; never
// translate arbitrary free text or customer names through a generic pattern.
const sentencePatterns=Object.keys(messages).filter(key=>/\{\w+\}/.test(key)&&key.split('{')[0].trim().length>=8).map(key=>{
  const names:string[]=[]
  const segments=key.split(/(\{\w+\})/g).map(part=>{
    if(/^\{\w+\}$/.test(part)){names.push(part.slice(1,-1));return '(.+?)'}
    return part.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')
  })
  return {key,names,prefix:key.split('{')[0],pattern:new RegExp('^'+segments.join('')+'$')}
})
export function translate(locale: Locale, source: string, values?: Record<string, string | number>): string {
  const key=source.replace(/\s+/g,' ').trim()
  if(locale!=='fr'&&!messages[key]&&!values){
    for(const item of sentencePatterns){
      if(!key.startsWith(item.prefix))continue
      const match=item.pattern.exec(key)
      if(match)return translate(locale,item.key,Object.fromEntries(item.names.map((name,i)=>[name,match[i+1]])))
    }
  }
  const result = locale === 'fr' ? source : messages[key]?.[locale === 'ar' ? 0 : 1] ?? source
  return result.replace(/\{(\w+)\}/g, (token, key) => values?.[key] == null ? token : String(values[key]))
}
